vector<ll> generate_powers(ll base, ll max_val) {
    vector<ll> powers;
    if (base == 1) {
        powers.push_back(1);
        return powers;
    }
    ll current = 1;
    while (current <= max_val) {
        powers.push_back(current);
        if (current > max_val / base) break;
        current *= base;
    }
    return powers;
}

int main() {
    ll x, y, l, r;
    cin >> x >> y >> l >> r;

    vector<ll> x_powers = generate_powers(x, r);
    vector<ll> y_powers = generate_powers(y, r);

    set<ll> unlucky;
    for (ll a : x_powers) {
        for (ll b : y_powers) {
            ll sum = a + b;
            if (sum >= l && sum <= r) {
                unlucky.insert(sum);
